/// The three files every page loads — stylesheet, htmx, Umbral's own script —
/// served by Umbral itself (Handlers/Assets.fs) instead of a CDN. An identity
/// provider's pages carry credentials, so they run no code from anyone else, and
/// an instance with no internet still renders.
///
/// They are embedded resources (Umbral.fsproj), not files under wwwroot: the app
/// stays one assembly and a TestServer-hosted app needs no content root. The
/// sources are in src/Umbral/Assets/; `umbral.css` is generated by build-css.sh.
module Umbral.Views.Assets

open System
open System.IO
open System.Reflection
open System.Security.Cryptography

type Asset =
    {
        /// Where it is served from
        Path: string
        ContentType: string
        Bytes: byte array
        /// Quoted, as the ETag header wants it
        ETag: string
        /// What a page links to: `Path` plus a content hash, so a new image means
        /// a new URL and the year-long immutable caching never serves stale code.
        Href: string
    }

let private readResource (name: string) : byte array =
    use stream = Assembly.GetExecutingAssembly().GetManifestResourceStream name

    match stream with
    | null -> failwith $"The embedded resource '{name}' is missing from the Umbral assembly: check the EmbeddedResource items in Umbral.fsproj."
    | stream ->
        use memory = new MemoryStream()
        stream.CopyTo memory
        memory.ToArray()

let private load (resource: string) (path: string) (contentType: string) : Asset =
    let bytes = readResource resource
    let hash = Convert.ToHexString(SHA256.HashData bytes).ToLowerInvariant()

    { Path = path
      ContentType = contentType
      Bytes = bytes
      ETag = $"\"{hash}\""
      Href = $"{path}?v={hash.Substring(0, 12)}" }

let css = load "umbral.css" "/assets/umbral.css" "text/css; charset=utf-8"
let script = load "umbral.js" "/assets/umbral.js" "text/javascript; charset=utf-8"
let htmx = load "htmx.min.js" "/assets/htmx.min.js" "text/javascript; charset=utf-8"

let all = [ css; script; htmx ]
